function escapeHTML(s){return s.replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
function addMessage(text,who='assistant'){const el=document.createElement('article');el.className='message '+(who==='user'?'user':'assistant');const av=document.createElement('div');av.className='message-avatar';av.textContent=who==='user'?'ن':'✦';const bubble=document.createElement('div');bubble.className='bubble';bubble.innerHTML=escapeHTML(text).replace(/\n/g,'<br>');el.append(av,bubble);conversation.append(el);el.scrollIntoView({behavior:'smooth',block:'nearest'});return bubble}
function localAnswer(q){const s=q.toLowerCase();if(/وام|فرزندآوری|تسهیلات|ازدواج/.test(s))return 'برای پیگیری وام، ابتدا نوع تسهیلات را مشخص کنید و فقط از درگاه رسمی بانک یا سامانه دولتی مربوط اقدام کنید.\n\n۱) شرایط و مدارک را در اطلاعیه رسمی همان طرح بررسی کنید.\n۲) مدارک هویتی و اطلاعات لازم را آماده کنید؛ رمز، کد پیامکی یا اطلاعات کارت بانکی را در این گفت‌وگو ننویسید.\n۳) از درگاه رسمی معرفی‌شده در اطلاعیه ثبت‌نام کنید و کد رهگیری را نزد خود نگه دارید.\n۴) شرایط، مبلغ و مهلت‌ها ممکن است تغییر کنند؛ پیش از ثبت نهایی، منبع رسمی را دوباره بررسی کنید.\n\nاین پاسخ نسخه نمایشی است و هنوز به جست‌وجوی زنده وصل نیست.';
if(/خودرو|ساینا|ایران.?خودرو|سایپا/.test(s))return 'برای ثبت‌نام خودرو، ابتدا مشخص کنید کدام شرکت و کدام طرح فروش مدنظرتان است.\n\n۱) اطلاعیه فروش را فقط در وب‌سایت رسمی شرکت خودروساز بخوانید.\n۲) تاریخ شروع و پایان، شرایط سنی، محدودیت‌ها و مبلغ پیش‌پرداخت را بررسی کنید.\n۳) آدرس سایت را دقیق بررسی کنید و از لینک‌های تبلیغاتی ناشناس یا پرداخت به اشخاص دوری کنید.\n۴) پس از ثبت درخواست، رسید و کد پیگیری را نگه دارید.\n\nمن در این نسخه امکان بررسی زنده بازبودن ثبت‌نام یا تأیید شرایط روز را ندارم.';
if(/تامین اجتماعی|تأمین اجتماعی|بیمه|بازنشستگی/.test(s))return 'برای خدمات تأمین اجتماعی، از درگاه رسمی سازمان تأمین اجتماعی وارد شوید و خدمت موردنظر را انتخاب کنید.\n\n۱) نشانی سامانه را از منبع رسمی سازمان پیدا کنید.\n۲) برای مشاهده سوابق یا خدمات شخصی، از روش ورود رسمی استفاده کنید.\n۳) اگر به رمز یک‌بارمصرف نیاز دارید، آن را فقط در خود سامانه رسمی وارد کنید؛ اینجا نفرستید.\n۴) رسید یا شماره پیگیری را نگه دارید.\n\nبرای راهنمایی دقیق‌تر، نام خدمت را بگویید؛ مثلاً مشاهده سوابق بیمه یا دریافت فیش مستمری.';
if(/مالیات|اظهارنامه|مالیاتی/.test(s))return 'برای امور مالیاتی، ابتدا نوع درخواست را مشخص کنید: پرونده مالیاتی، اظهارنامه، پرداخت یا پیگیری ابلاغیه.\n\n۱) وارد درگاه رسمی سازمان امور مالیاتی شوید؛ نشانی را از منبع معتبر بررسی کنید.\n۲) با روش احراز هویت رسمی وارد شوید.\n۳) پیش از ارسال اظهارنامه یا پرداخت، اطلاعات را با دقت بازبینی کنید.\n۴) رسید پرداخت و کد رهگیری را نگه دارید.\n\nمهلت‌ها و قوانین ممکن است تغییر کنند؛ این نسخه هنوز اطلاعات روز را زنده بررسی نمی‌کند.';
if(/ثبت احوال|شناسنامه|کارت ملی|مدرک هویتی/.test(s))return 'برای خدمات ثبت احوال و مدارک هویتی، از وب‌سایت رسمی سازمان ثبت احوال یا درگاه ملی خدمات دولت هوشمند شروع کنید. نوع خدمت را دقیق مشخص کنید؛ مانند پیگیری کارت ملی، درخواست گواهی یا اصلاح اطلاعات. مدارک، هزینه و امکان انجام غیرحضوری بسته به خدمت متفاوت است. اطلاعات هویتی کامل را در چت عمومی وارد نکنید.';
if(/بانک|کارت بانکی|حساب|شبا/.test(s))return 'برای امور بانکی، فقط از اپلیکیشن یا وب‌سایت رسمی بانک خود استفاده کنید. هیچ‌وقت رمز پویا، رمز کارت، CVV2 یا کد پیامکی را برای راهنمایی ارسال نکنید. اگر موضوع انتقال وجه یا تراکنش مشکوک است، از شماره پشتیبانی درج‌شده روی کارت یا وب‌سایت رسمی بانک پیگیری کنید.';
if(/سلام|درود|خسته نباشید/.test(s))return 'سلام، خوش آمدید. من در نسخه نمایشی کافی‌نت هوشمند هستم. بگویید برای کدام خدمت اداری یا اینترنتی ایران راهنمایی می‌خواهید تا مسیر کلی را توضیح بدهم.';
return 'متوجه شدم که برای «'+q+'» راهنمایی می‌خواهید. این نسخه هنوز به موتور هوش مصنوعی و جست‌وجوی زنده وصل نشده، بنابراین نمی‌توانم مراحل روز را تأیید کنم.\n\nبرای شروع، نام دقیق خدمت یا سازمان را بگویید. در هر حال، مراحل و شرایط را پیش از اقدام در وب‌سایت رسمی همان سازمان بررسی کنید و رمزها، کدهای پیامکی یا اطلاعات بانکی را اینجا ننویسید.'}
async function ask(q){$('#welcome').hidden=true;if(navigator.onLine===false){addMessage(q,'user');addMessage('لطفاً اینترنت خود را روشن کنید.');return}const hs=[...conversation.querySelectorAll('.message')].slice(-8).filter(el=>!el.querySelector('button,a.go,.trust,.steps')).map(el=>[el.classList.contains('user')?'user':'assistant',((el.querySelector('.bubble')||{}).textContent||'').slice(0,500)]).filter(x=>x[1]&&x[1]!=='در حال بررسی درخواست…').map(x=>({role:x[0],content:x[1]}));addMessage(q,'user');const b=addMessage('در حال بررسی درخواست…');$('#sendBtn').disabled=true;try{let answer,srcs=[];if(CONFIG.API_BASE){const r=await fetch(CONFIG.API_BASE.replace(/\/$/,'')+'/api/chat',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({message:q,context:window.khCtx||'',history:hs})});if(!r.ok)throw new Error('service');const d=await r.json();answer=d.answer||'پاسخی دریافت نشد.';srcs=(d.sources||[]).filter(s=>s&&/^https:\/\//.test(s.url))}else{await new Promise(r=>setTimeout(r,450));answer=localAnswer(q)}b.innerHTML=escapeHTML(answer).replace(/\n/g,'<br>');if(srcs.length)b.insertAdjacentHTML('beforeend','<div class="srcs">منبع: '+srcs.slice(0,3).map(s=>'<a href="'+encodeURI(s.url)+'" target="_blank" rel="noopener noreferrer">'+escapeHTML(s.title||s.url)+' ↗</a>').join(' · ')+'</div>')}catch(e){b.textContent='فعلاً پاسخ‌گویی آنلاین در دسترس نیست. لطفاً بعداً دوباره تلاش کنید؛ اطلاعات حساس وارد نکنید.'}finally{$('#sendBtn').disabled=false;input.focus()}}
$('#chatForm').addEventListener('submit',e=>{e.preventDefault();const q=input.value.trim();if(!q)return;input.value='';input.style.height='auto';ask(q)});
