let recognition=null;const mic=$('#micBtn');mic.addEventListener('click',()=>{if(window.KHNative&&window.khDictate){window.khDictate();return}const SR=window.SpeechRecognition||window.webkitSpeechRecognition;if(!SR){openModal('ورودی صوتی','<p>مرورگر فعلی از تشخیص گفتار پشتیبانی نمی‌کند. از نسخه جدید Chrome استفاده کنید یا درخواست را تایپ کنید.</p>');return}if(recognition){recognition.stop();return}recognition=new SR();recognition.lang='fa-IR';recognition.interimResults=true;recognition.maxAlternatives=1;const base=input.value,PH=input.placeholder;mic.classList.add('recording');input.placeholder='در حال گوش دادن… صحبت کنید';recognition.onresult=e=>{let t='';for(const r of e.results)t+=r[0].transcript;input.value=(base+' '+t).trim();input.dispatchEvent(new Event('input'))};recognition.onerror=e=>{const deny='اجازه دسترسی به میکروفون داده نشده است. در تنظیمات مرورگر، میکروفون را برای این سایت مجاز کنید. اگر صفحه داخل قاب باز شده، آن را در یک تب جدید باز کنید.';const m={'not-allowed':deny,'service-not-allowed':deny,'no-speech':'صدایی شنیده نشد. دوباره تلاش کنید.','audio-capture':'میکروفونی پیدا نشد.','network':'برای تشخیص گفتار به اینترنت نیاز است.'};if(e.error!=='aborted')openModal('ورودی صوتی','<p>'+(m[e.error]||'تشخیص گفتار با خطا مواجه شد.')+'</p>')};recognition.onend=()=>{mic.classList.remove('recording');input.placeholder=PH;recognition=null;input.focus()};try{recognition.start()}catch(err){recognition.onend()}});
